def records_from(exchange):
    core.ReasonOracle.success(exchange, statuses=(200,), require_non_empty=False)
    candidates = exchange.body_list
    if candidates is None:
        body = exchange.body or {}
        candidates = body.get("records") or body.get("items") or body.get("results")
        if candidates is None and isinstance(body.get("data"), list):
            candidates = body["data"]
        if candidates is None and isinstance(body.get("data"), dict):
            nested = body["data"]
            candidates = nested.get("records") or nested.get("items") or nested.get("results")
    if candidates is None:
        candidates = []
    if not isinstance(candidates, list) or any(not isinstance(item, dict) for item in candidates):
        raise core.HarnessError("Runtime record list has an unsupported shape")
    return candidates


def record_from(exchange):
    core.ReasonOracle.success(exchange, statuses=(200,), require_non_empty=True)
    body = exchange.body or {}
    nested_record = None
    if isinstance(body.get("data"), dict):
        nested_record = body["data"].get("record")
    for candidate in (body, body.get("record"), body.get("data"), nested_record):
        if isinstance(candidate, dict) and isinstance(candidate.get("id"), str) and isinstance(candidate.get("data"), dict):
            return candidate
    raise core.HarnessError("Runtime detail response has no canonical record id/data")


def action_definitions(exchange):
