    return candidates


def output_from(exchange):
    body = exchange.body or {}
    candidates = [body]
    for key in ("data", "result", "output"):
        if isinstance(body.get(key), dict):
            candidates.append(body[key])
    for candidate in candidates:
        keys = ("approval_id", "lead_id", "customer_id")
        if all(isinstance(candidate.get(key), str) and candidate.get(key) for key in keys):
            return {key: candidate[key] for key in keys}
    raise core.HarnessError("positive Action result lacks non-empty approval/lead/customer identities")


def relation_id(value):
    if isinstance(value, str) and value:
        return value
    if isinstance(value, dict):
        for key in ("id", "record_id", "value"):
            if isinstance(value.get(key), str) and value.get(key):
                return value[key]
    raise core.HarnessError("Runtime relation value has no opaque target identity")


def stable_error(exchange):
    body = exchange.body or {}
    value = body.get("code") or body.get("error")
    if isinstance(value, dict):
        value = value.get("code")
    if not value and isinstance(body.get("details"), dict):
        value = body["details"].get("code")
    return str(value or exchange.error_code or "")


