            raise core.HarnessError(
                "resolved approval does not reference one non-empty qualified lead")
        before_closure, before_sha = durable_closure(
            runtime, denied_actor, approval_id, lead_id)
        if before_closure["customers"]:
            raise core.HarnessError("fresh pending approval already has a customer")

        action_path = "/objects/%s/records/%s/actions/%s" % (
            urllib.parse.quote("conversion_approval", safe=""),
            urllib.parse.quote(approval_id, safe=""),
            urllib.parse.quote(action_key, safe=""),
        )
