            runtime, "POST", action_path, session=denied_actor,
            body={"data": {"request_id": denied_key}}, idempotency_key=denied_key)
        denied.error_code = stable_error(denied)
        _, after_denied_sha = durable_closure(
            runtime, denied_actor, approval_id, lead_id)
        core.ReasonOracle.rejection(
            denied, statuses=(403,), error_code="backend.action.permission_denied",
            before_sha256=before_sha, after_sha256=after_denied_sha)

        command_key = core.new_probe_token("j07-approve")
        positive = request(
            runtime, "POST", action_path, session=director,
            body={"data": {"request_id": command_key}}, idempotency_key=command_key)
        core.ReasonOracle.success(
            positive, statuses=(200, 201), require_non_empty=True)
        positive_output = output_from(positive)
        if positive_output["approval_id"] != approval_id or positive_output["lead_id"] != lead_id:
            raise core.HarnessError(
                "positive Action output does not name the resolved target identities")

        approval_after = get_record(
            runtime, denied_actor, "conversion_approval", approval_id)
        lead_after = get_record(runtime, denied_actor, "lead", lead_id)
        customer_after = get_record(
            runtime, denied_actor, "customer", positive_output["customer_id"])
        if approval_after["data"].get("status") != "approved":
            raise core.HarnessError(
                "actor-visible approval read-back is not approved")
        if lead_after["data"].get("status") != "converted":
            raise core.HarnessError("actor-visible lead read-back is not converted")
